import{z as B,x as A,o as t,c as p,q as n,j as i,D as r,d as E,s as l,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"增量解析 tree-sitter","description":"","frontmatter":{"title":"增量解析 tree-sitter","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/incremental-parsing.md","filePath":"cs/incremental-parsing.md","lastUpdated":1791063341000}'),d={name:"cs/incremental-parsing.md"};function m(D,e,c,h,u,g){const s=A("Mermaid");return t(),p("div",null,[e[2]||(e[2]=n('<h1 id="增量解析-tree-sitter" tabindex="-1">增量解析 tree-sitter <a class="header-anchor" href="#增量解析-tree-sitter" aria-label="Permalink to &quot;增量解析 tree-sitter&quot;">​</a></h1><div class="epigraph"><p>源文本改了一处，分析树只重算受影响的区间；编辑器要的是毫秒级更新，不是整文件再跑一遍 yyparse。</p><footer>—— 据 Wagner and Graham, Incremental Analysis of Real Programming Languages, 1998；tree-sitter 设计文档整理</footer></div><p>上一课<a href="/cs/parse-error-recovery">错误恢复</a>让整文件分析可以带着诊断走完。编辑会话里每次击键都全量 LALR 太贵。缺口是<strong>增量</strong>：把旧树与编辑区间对齐，复用未改子树。tree-sitter 用 GLR 方言与显式树，是这一课的工程锚点，不是唯一理论。本课不重写 GLR 分叉。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全量分析 \\(O(n)\\) 对百万行尚可，对每次击键的交互不行。增量：保留具体语法树（带源区间），编辑映射到插入/删除区间，从该区间的祖先重新分析，其它子树当记号或子语言复用。缺口是<strong>复用条件</strong>，不是再定义 CFG。</p><p><span class="marginnote">术语翻译：「具体语法树」就是连括号、分号、逗号都原样留着的树；编译器常用的「抽象语法树」会把这些纯语法细节扔掉。tree-sitter 坚持用具体树，正是因为每个节点都带源码区间，编辑来的时候才能按位置对齐、判断哪些子树没被碰到。</span></p><p>错误节点：tree-sitter 在失败处插 <code>ERROR</code>，以便高亮与缩进仍工作。这与编译器的 <code>error</code> 产生式同类，目标是编辑器而非代码生成。</p><h3 id="复用不是「字节没改就语义没改」" tabindex="-1">复用不是「字节没改就语义没改」 <a class="header-anchor" href="#复用不是「字节没改就语义没改」" aria-label="Permalink to &quot;复用不是「字节没改就语义没改」&quot;">​</a></h3><p>宏、C 预处理器、依赖头文件会使「没改的区间」语义变。tree-sitter 默认按文件、按语言文法，不跑 cpp。真正编译器的增量要另做依赖图——本课只钉语法树增量。</p><p><span class="marginnote">Wagner–Graham 1998（PLDI）讨论真实语言的增量分析。tree-sitter 公开设计：GLR、显式冲突、增量。本课不把 Language Server 协议当文法理论。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>保存旧树与旧文本。应用编辑，得新文本与脏区间。从脏区间对应的旧节点向上找到可再分析的边界（如函数、块）。在该子语言上跑分析器，把新子树接回。token 复用：词法也可增量，改空白尽量不动后继树。</p>',12)),(t(),i(o,null,{default:r(()=>[l(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E6%97%A7%E6%A0%91%22%5D%20--%3E%20EDIT%5B%22%E7%BC%96%E8%BE%91%E5%8C%BA%E9%97%B4%22%5D%0A%20%20EDIT%20--%3E%20RE%5B%22%E5%B1%80%E9%83%A8%E5%86%8D%E5%88%86%E6%9E%90%22%5D%0A%20%20OLD%20--%3E%20REUSE%5B%22%E6%9C%AA%E8%84%8F%E5%AD%90%E6%A0%91%E5%A4%8D%E7%94%A8%22%5D%0A%20%20RE%20--%3E%20NEW%5B%22%E6%96%B0%E6%A0%91%22%5D%0A%20%20REUSE%20--%3E%20NEW%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("p",null,"与 Pratt/手写下降：增量更难，因为下降的调用栈没有显式区间树。这是「生成树、带位移」的动机。",-1)),e[4]||(e[4]=a("h2",{id:"机制",tabindex:"-1"},[E("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=a("p",null,"最坏仍可能接近全量（在文件头改一个括号）。摊还在局部编辑上接近脏区大小。多语言嵌入（Markdown 里的代码块）靠外部扫描器切片段，各片段独立文法——点名，不写完。",-1)),e[6]||(e[6]=a("p",null,"编译器中端（SSA、数据流）增量是另一问题：语法树没变的函数仍可能因内联热度重优化。本课停在前端树。",-1)),e[7]||(e[7]=a("p",null,"最坏情况为什么逼近全量？看编辑位置把复用边界推到哪里：",-1)),(t(),i(o,null,{default:r(()=>[l(s,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E5%9C%A8%E6%96%87%E4%BB%B6%E5%A4%B4%E6%94%B9%E4%BA%86%E4%B8%80%E4%B8%AA%E6%8B%AC%E5%8F%B7%22%5D%20--%3E%20D%5B%22%E8%84%8F%E5%8C%BA%E9%97%B4%E8%90%BD%E5%9C%A8%E6%96%87%E4%BB%B6%E5%BC%80%E5%A4%B4%22%5D%0A%20%20D%20--%3E%20ANC%5B%22%E8%84%8F%E8%8A%82%E7%82%B9%E7%9A%84%E7%A5%96%E5%85%88%E6%98%AF%E9%A1%B6%E5%B1%82%E5%9D%97%22%5D%0A%20%20ANC%20--%3E%20BIG%5B%22%E5%8F%AF%E5%A4%8D%E7%94%A8%E7%9A%84%E8%BE%B9%E7%95%8C%E8%A2%AB%E9%A1%B6%E5%88%B0%E6%8E%A5%E8%BF%91%E5%85%A8%E6%96%87%E4%BB%B6%22%5D%0A%20%20BIG%20--%3E%20RE%5B%22%E5%86%8D%E5%88%86%E6%9E%90%E8%8C%83%E5%9B%B4%20%E2%89%88%20%E6%95%B4%E4%B8%AA%E6%96%87%E4%BB%B6%22%5D%0A%20%20RE%20--%3E%20T%5B%22%E6%91%8A%E8%BF%98%E4%BE%9D%E8%B5%96%EF%BC%9A%E5%A4%9A%E6%95%B0%E7%BC%96%E8%BE%91%E9%83%BD%E8%90%BD%E5%9C%A8%E5%B0%8F%E5%87%BD%E6%95%B0%E9%87%8C%22%5D%0A"})]),fallback:r(()=>[...e[1]||(e[1]=[E(" Loading... ",-1)])]),_:1})),e[8]||(e[8]=n('<p><span class="marginnote">数字实例：10 万行的文件里改一个 20 行函数中的变量名，增量解析只需重跑那几十行，比全量快数千倍——这正是编辑器能跟手的原因；但把括号改在文件头，这次就退化成全量，只能靠「大多数编辑是局部的」把平均代价摊薄。</span></p><p><span class="marginnote">常见误区：初学者容易以为「字节没改就语义没改」。C 里改一个宏定义，后面几百处用到它的行一个字节都没动、语义却全变了。tree-sitter 不跑预处理器，所以它的「复用」只到语法层面；指望它发现语义变化是搞错了边界。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不实现 tree-sitter 的 C 运行时，不讲查询语言。后课默认：编辑器增量 ≠ 编译器全量语义。下一课从树到属性：属性文法，给节点挂值而不必立刻手写访问者。</p><p>不要把增量解析当成类型检查的增量；名字解析跨文件时脏区会跳。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>增量：脏区间再分析，未改子树复用。</li><li>tree-sitter：GLR 树 + 错误节点，服务编辑器。</li><li>预处理器与跨文件语义不在复用假设里。</li><li>出处：Wagner and Graham, 1998；tree-sitter 文档；对照 Tomita GLR。</li></ul>',7))])}const T=B(d,[["render",m]]);export{f as __pageData,T as default};
